"""Load and validate the three CrisisBench splits; build the modelling frame.

Column aliases are resolved to a canonical schema:
    id, event, source, text (raw), lang, lang_conf, label, text_clean
`text_clean` is produced by src/preprocess.py when the release has no such
column (the v1.0 all_data_en release ships raw `text`).  event/source/id/lang/
lang_conf are kept for descriptive use but are structurally excluded from any
feature matrix (R2).
"""
from __future__ import annotations

import re

import pandas as pd

import src.acquire
import src.config as cfg
from src.preprocess import clean_series


class DataError(RuntimeError):
    pass


def _resolve(df: pd.DataFrame) -> pd.DataFrame:
    out = pd.DataFrame(index=df.index)
    for canon, aliases in cfg.COLUMN_ALIASES.items():
        found = next((a for a in aliases if a in df.columns), None)
        if found is not None:
            out[canon] = df[found]
    if "text" not in out.columns or "label" not in out.columns:
        raise DataError(f"Could not resolve text/label columns in {list(df.columns)}")
    for c in ("event", "source", "id", "lang", "lang_conf"):
        if c not in out.columns:
            out[c] = None
    out["label"] = out["label"].astype(str).str.strip()
    out["text"] = out["text"].astype(str)
    return out


def load_splits(manifest: dict) -> dict[str, pd.DataFrame]:
    """Load Train/Development/Test, generate text_clean, validate (R1, R2, R14)."""
    splits: dict[str, pd.DataFrame] = {}
    for split in ("train", "dev", "test"):
        df = _resolve(src.acquire.read_tsv(manifest["files"][split]))
        df["text_clean"] = clean_series(df["text"])
        df["split"] = split
        splits[split] = df

    # hard gates
    for split, expected in cfg.EXPECTED_SIZES.items():
        if len(splits[split]) != expected:
            raise DataError(
                f"{split}: {len(splits[split])} rows != expected {expected}"
            )
    n_empty = int((splits["train"]["text_clean"].str.len() == 0).sum()) \
        + int((splits["dev"]["text_clean"].str.len() == 0).sum()) \
        + int((splits["test"]["text_clean"].str.len() == 0).sum())
    if n_empty > 0.01 * cfg.EXPECTED_TOTAL:
        raise DataError(f"{n_empty} empty cleaned texts (>{1}% of the corpus)")
    if splits["train"]["text_clean"].isna().any() or \
            splits["dev"]["text_clean"].isna().any() or \
            splits["test"]["text_clean"].isna().any():
        raise DataError("NaN text_clean after preprocessing")

    all_labels = sorted(
        set(splits["train"]["label"]) | set(splits["dev"]["label"])
        | set(splits["test"]["label"])
    )
    if len(all_labels) != cfg.N_LABELS:
        raise DataError(f"{len(all_labels)} labels != {cfg.N_LABELS}: {all_labels}")
    unseen = (set(splits["test"]["label"]) - set(splits["train"]["label"])
              | set(splits["test"]["label"]) - set(splits["dev"]["label"]))
    if unseen:
        raise DataError(f"Test labels unseen in Train/Dev: {unseen}")
    return splits


def all_labels(splits: dict[str, pd.DataFrame]) -> list[str]:
    return sorted(
        set(splits["train"]["label"]) | set(splits["dev"]["label"])
        | set(splits["test"]["label"])
    )


def label_counts(splits: dict[str, pd.DataFrame]) -> dict:
    return {
        split: splits[split]["label"].value_counts().to_dict()
        for split in splits
    }


def token_stats(df: pd.DataFrame) -> dict:
    n_tok = df["text_clean"].str.split().str.len()
    return {
        "mean_tokens": round(float(n_tok.mean()), 2),
        "p95_tokens": round(float(n_tok.quantile(0.95)), 2),
        "empty": int((n_tok == 0).sum()),
    }


def cyclone_mask(df: pd.DataFrame, level: str) -> pd.Series:
    """Case-insensitive event-field filter (A11)."""
    regex = {"strict": cfg.CYCLONE["strict_regex"],
             "broad": cfg.CYCLONE["broad_regex"]}[level]
    return df[cfg.CYCLONE["event_column"]].astype(str).str.contains(
        regex, case=False, regex=True
    )


def cyclone_subset(splits: dict[str, pd.DataFrame], level: str) -> dict:
    return {split: splits[split][cyclone_mask(splits[split], level)]
            for split in ("train", "dev", "test")}


def check_no_leakage_columns(df: pd.DataFrame) -> None:
    """Guard: the frame handed to the vectoriser must not carry metadata (R2)."""
    present = [c for c in cfg.FORBIDDEN_FEATURE_COLUMNS if c in df.columns]
    if present:
        raise DataError(f"Forbidden metadata columns present: {present}")

